-- Remove SELECT overlap from broad write policies.
drop policy if exists "Admins e donos gerenciam catálogos" on public.catalogos;
create policy "Admins e donos inserem catálogos" on public.catalogos for insert to authenticated with check (has_role(auth.uid(),'admin'::app_role) or has_role(auth.uid(),'dono_processo'::app_role));
create policy "Admins e donos atualizam catálogos" on public.catalogos for update to authenticated using (has_role(auth.uid(),'admin'::app_role) or has_role(auth.uid(),'dono_processo'::app_role)) with check (has_role(auth.uid(),'admin'::app_role) or has_role(auth.uid(),'dono_processo'::app_role));
create policy "Admins e donos excluem catálogos" on public.catalogos for delete to authenticated using (has_role(auth.uid(),'admin'::app_role) or has_role(auth.uid(),'dono_processo'::app_role));
