drop policy if exists "fases_processo_write_policy" on public.fases_processo;
create policy "fases_processo_insert_policy" on public.fases_processo for insert to authenticated with check (is_platform_master_admin() or exists (select 1 from public.candidaturas c where c.id=fases_processo.candidatura_id and can_administer_tenant(c.tenant_id)));
create policy "fases_processo_update_policy" on public.fases_processo for update to authenticated using (is_platform_master_admin() or exists (select 1 from public.candidaturas c where c.id=fases_processo.candidatura_id and can_administer_tenant(c.tenant_id))) with check (is_platform_master_admin() or exists (select 1 from public.candidaturas c where c.id=fases_processo.candidatura_id and can_administer_tenant(c.tenant_id)));
create policy "fases_processo_delete_policy" on public.fases_processo for delete to authenticated using (is_platform_master_admin() or exists (select 1 from public.candidaturas c where c.id=fases_processo.candidatura_id and can_administer_tenant(c.tenant_id)));
