create policy "resultados_provas_update_policy" on public.resultados_provas for update to authenticated using (is_platform_master_admin() or exists (select 1 from public.candidaturas c where c.id=resultados_provas.candidatura_id and can_administer_tenant(c.tenant_id))) with check (is_platform_master_admin() or exists (select 1 from public.candidaturas c where c.id=resultados_provas.candidatura_id and can_administer_tenant(c.tenant_id)));
create policy "resultados_provas_delete_policy" on public.resultados_provas for delete to authenticated using (is_platform_master_admin() or exists (select 1 from public.candidaturas c where c.id=resultados_provas.candidatura_id and can_administer_tenant(c.tenant_id)));
drop policy if exists "visualizacoes_rh_write_policy" on public.visualizacoes_rh;
create policy "visualizacoes_rh_insert_policy" on public.visualizacoes_rh for insert to authenticated with check (is_platform_master_admin() or rh_id=((select auth.uid()))::text);
create policy "visualizacoes_rh_update_policy" on public.visualizacoes_rh for update to authenticated using (is_platform_master_admin() or rh_id=((select auth.uid()))::text) with check (is_platform_master_admin() or rh_id=((select auth.uid()))::text);
create policy "visualizacoes_rh_delete_policy" on public.visualizacoes_rh for delete to authenticated using (is_platform_master_admin() or rh_id=((select auth.uid()))::text);